"""Render the verified complete 7 x 4 x 6 matrix in both languages."""
import json,statistics,re
import build_latest as old
ROOT=old.ROOT
ORDER=old.ORDER
LABELS=old.LABELS
tab=old.tab
tr=old.tr
A=json.loads((ROOT/'data/matrix/analysis.json').read_text('utf-8'))

def group(scope):return sorted(old.group(scope),key=lambda r:-r['ndcg10'])
def name(k,lang):return old.name(k,lang)
def combo(r,lang):return old.combo(r,lang)
def pick(e,rr):return next(r for r in group('all') if r['embedding']==e and r['reranker']==rr)
def page(path,title,body,lang):
 s=old.page(path,title,body,lang)
 return s.replace('2026-10-24 01:47','2026-10-26 05:31').replace('24 Oct 2026, 01:47','26 Oct 2026, 05:31').replace('14,478','73,164')
def findings(lang):
 t=lambda z,e:tr(z,e,lang)
 items=[(t('小型 Embedder，也能搭出接近領先的效果。','A small embedder can approach the leading score.'),t('Qwen 0.6B＋4B 重排器的六分項 nDCG 為 0.7893，與 Qwen 4B＋4B 的 0.7926 相差 0.0033；權重從 7.972 降至 4.581 GiB，少約 42.5%。仍需承擔 4B 重排器的等待時間。','Qwen 0.6B + 4B reranking reaches 0.7893 macro nDCG, 0.0033 below Qwen 4B + 4B at 0.7926. Weights fall from 7.972 to 4.581 GiB, about 42.5% less. The 4B reranker still brings a substantial latency cost.')),
 (t('8B 並非每種組合都比較好。','8B does not lead in every configuration.'),t('Qwen 8B 是單獨檢索 nDCG 最高的模型，搭配 4B 重排器後也領先三個 MLQA 分項；六分項總平均則由 Qwen 4B＋4B 略高，差距僅 0.0009。不要把這個差距當成顯著勝出。','Qwen 8B leads standalone nDCG and, with 4B reranking, all three MLQA conditions. Qwen 4B + 4B has a slightly higher six-task mean, by just 0.0009. This is not evidence of a statistically significant win.')),
 (t('重排器更大，分數較高，也慢得多。','Larger rerankers score higher and take longer.'),t('七個 Embedder 各自的六分項平均，都以 Qwen 4B 重排器最高。它的重排時間中位數約 6.22 秒，0.6B 約 1.13 秒，BGE 約 0.85 秒。這是本機單輪逐題測量，並非正式服務的併發延遲。','For each of the seven embedders, Qwen 4B reranking gives the highest six-task mean nDCG. Pooled median reranking time is about 6.22 s, versus 1.13 s for 0.6B and 0.85 s for BGE. These are local single-run stage measurements, not production concurrency latency.'))]
 return '<section id="findings"><p class="eyebrow">WHAT THE FULL MATRIX REVEALS</p><h2>'+t('這次補齊組合後，看見什麼？','What does the complete matrix reveal?')+'</h2><div class="findings">'+''.join('<article class="finding"><h3>'+h+'</h3><p>'+b+'</p></article>' for h,b in items)+'</div><p class="small">'+t('以上為這套固定語料上的新比較，並不宣稱世界首次；未替28組計算全域信賴區間或多重比較校正。','These are new comparisons within this fixed corpus, not claims of first discovery. No global confidence intervals or multiplicity adjustment were computed for the 28 setups.')+' <a href="latest-methods.html#published">'+t('與官方評測對照','Compare with published evaluations')+' →</a></p></section>'
def recommendations(lang):
 t=lambda z,e:tr(z,e,lang)
 # Capacity bands are file-weight budgets, explicitly not device RAM requirements.
 choices=[('granite-97m-r2','standalone',t('極小權重｜不到 0.2 GiB','Tiny weights | under 0.2 GiB'),t('本次最小模型；查詢 embedding 中位數約 3.62 ms。適合先建立低成本基線，但排序品質較低。','The smallest tested model; median query embedding is about 3.62 ms. A low-cost baseline with lower ranking quality.')),
 ('embeddinggemma-2','standalone',t('輕量單模型｜不到 0.5 GiB','Light single model | under 0.5 GiB'),t('此容量範圍內，六分項 nDCG 高於 Granite；不需負擔逐筆重排時間。','Within this weight budget, six-task nDCG is higher than Granite, without a per-query reranking stage.')),
 ('bge-m3','standalone',t('低延遲單模型｜不到 1 GiB','Low-latency single model | under 1 GiB'),t('此權重範圍內、不加重排器時的最高 nDCG 組合；本機 query embedding 中位數約 7.67 ms。','Highest nDCG without reranking within this weight budget; local median query embedding is about 7.67 ms.')),
 ('bge-m3','qwen-reranker-0.6b',t('均衡配置｜不到 1.5 GiB','Balanced setup | under 1.5 GiB'),t('此容量範圍的最高 nDCG 組合。若只重視第一名命中率，同範圍可比較 Qwen 0.6B＋0.6B。BGE 重排器則可縮短重排等待。','Highest nDCG within this budget. For first-result hits, also compare Qwen 0.6B + 0.6B. BGE reranking offers a shorter reranking wait.')),
 ('bge-m3','qwen-reranker-4b',t('接近領先品質｜不到 5 GiB','Near-leading quality | under 5 GiB'),t('此容量範圍的最高 nDCG 組合，距整體最高約 0.0018；需要接受較慢的 4B 重排。','Highest nDCG within this budget, about 0.0018 below the overall leader; requires the slower 4B reranker.')),
 ('qwen-4b','qwen-reranker-4b',t('最高 nDCG 點估計｜不到 8 GiB','Highest nDCG estimate | under 8 GiB'),t('六分項平均數值最高；與 8B＋4B 的差距很小。若完全不加重排器，Qwen 8B 的平均 nDCG 最高。','Highest six-task mean estimate, narrowly ahead of 8B + 4B. Without reranking, Qwen 8B has the highest mean nDCG.'))]
 b='<section id="choose"><h2>'+t('依可負擔的模型容量與等待時間選擇','Choose by weight budget and acceptable wait')+'</h2><p>'+t('以下依六分項平均 nDCG，在各權重上限內挑選已測組合；低延遲單模型類別只比較不加重排器的設定。這是模型檔案容量，不是最低 RAM／VRAM；實際執行還需要向量索引、工作緩衝與系統空間。','These choices maximize six-task mean nDCG within each file-weight budget; the low-latency single-model category considers only setups without reranking. File size is not a minimum RAM/VRAM requirement: indexing, runtime buffers and the operating system need additional memory.')+'</p><div class="recommend-grid">'
 for e,rr,h,why in choices:
  r=pick(e,rr);b+='<article class="scorecard"><h3>'+h+'</h3><p><b>'+combo(r,lang)+'</b></p><p>'+f'nDCG {r["ndcg10"]:.4f} · Top-1 {r["top1"]*100:.2f}% · {r["weight_gib_sum"]:.3f} GiB'+'</p><p>'+why+'</p><a href="models/'+e+'.html">'+t('查看模型與完整配對','Model and all tested pairings')+' →</a></article>'
 return b+'</div><p class="small">'+t('僅在 M3 Ultra／256 GiB 測量速度。尚無一般筆電、CPU-only 或其他 GPU 的實測，不能據此承諾那些硬體的速度或可執行容量。','Latency was measured only on an M3 Ultra with 256 GiB. Laptop, CPU-only and other GPU performance or memory feasibility has not been measured.')+'</p></section>'
def home(lang):
 t=lambda z,e:tr(z,e,lang);pre='../' if lang else ''
 featured=[('qwen-4b','qwen-reranker-4b',t('最高 nDCG 點估計','Highest nDCG estimate')),('bge-m3','qwen-reranker-4b',t('不到 5 GiB 的品質選擇','Quality under 5 GiB')),('bge-m3','qwen-reranker-0.6b',t('不到 1.5 GiB 的均衡選擇','Balance under 1.5 GiB'))]
 cards=''
 for e,rr,tag in featured:
  r=pick(e,rr);cards+=f'<article class="scorecard"><span>{tag}</span><strong>{r["ndcg10"]:.4f}</strong><small>{t("六分項平均 nDCG@10","Six-task mean nDCG@10")}</small><b>{combo(r,lang)}</b><small>Top-1 {r["top1"]*100:.2f}% · {r["weight_gib_sum"]:.3f} GiB</small></article>'
 b=f'<section class="phase-hero"><p class="eyebrow">2026-10-26 · COMPLETE 28-SETUP MATRIX</p><h1>{t("28 種搜尋組合，<br>用同一套題目完整比較。","28 retrieval setups.<br>One consistent test matrix.")}</h1><p class="lead">{t("七個 Embedder，搭配不重排或三種重排器，全部完成六分項。先看綜合平均，再按語言、品質與模型容量挑選。","Seven embedders, each alone or with three rerankers, all tested in six conditions. Start with the overall mean, then choose by language, quality and model size.")}</p><div class="headline-scores">{cards}</div><p class="macro-note">{t("nDCG 衡量前十名排序品質，越接近 1 越好，不是命中百分比。Top-1 是第一筆命中的比例。六分項各占 1/6；兩種平均都依本測試的相關性標準計算，不代表所有領域的普遍排名。","nDCG measures top-ten ranking quality: closer to 1 is better, and it is not a hit percentage. Top-1 is the first-result hit rate. Each condition weighs 1/6; both averages use this study’s relevance definitions and are not universal rankings.")} <a href="latest-methods.html#average">{t("平均怎麼算","How averages work")} →</a></p></section>'
 b+='<div class="evidence-strip">'+''.join('<div><strong>'+v+'</strong><span>'+l+'</span></div>' for v,l in [('28',t('完整受測組合','complete setups')),('6',t('一致測試分項','fixed conditions')),('73,164',t('逐題測量／168組摘要','measurements / 168 summaries')),('2,613',t('資料集內唯一題目','dataset-qualified queries'))])+'</div><p class="context-line">Q8_0 · M3 Ultra / Metal · 256 GiB · '+t('同一題在28種組合重測，不能視為73,164個獨立樣本。','Each query is measured across 28 setups; these are not 73,164 independent samples.')+'</p>'
 b+=findings(lang)
 b+='<section id="results"><h2>'+t('完整比較：切換分項、排序指標與重排器','Compare every setup: task, metric and reranker')+'</h2><p>'+t('綠色是相同 Embedder 單獨使用的分數；橘色是重排後提升，紅色斜線是下降。圖表預設顯示前7名，可展開全部。表格列出所選條件的全部組合。','Teal shows the same embedder alone, orange the reranking gain, and red hatching a loss. The chart initially shows the top seven; expand it to see all. The table includes every setup matching your selection.')+'</p><div class="controls">'
 scopes=[('all',t('綜合平均｜六分項等權','Overall | six equal-weight conditions')),('mlqa',t('MLQA 平均｜三方向等權','MLQA | three equal-weight directions'))]+[(d,LABELS[d][lang]) for d in ORDER]
 metrics=[('ndcg10',t('nDCG@10｜前十名排序品質','nDCG@10 | top-ten ranking quality')),('top1',t('Top-1｜第一名命中率','Top-1 | first-result hit rate')),('mrr10','MRR@10'),('recall50','Recall@50')]
 rr=[('all',t('全部28組','All 28 setups')),('standalone',t('不加重排器','No reranker'))]+[(r,name(r,lang)) for r in A['reranker_timing']]
 for key,label,options in [('scope',t('測試範圍','Test scope'),scopes),('metric',t('品質指標','Quality metric'),metrics),('reranker',t('顯示重排器','Show reranker'),rr)]:b+='<label>'+label+f'<select id="{key}">'+''.join(f'<option value="{k}">{v}</option>' for k,v in options)+'</select></label>'
 b+='</div><p id="scope-note" class="note" aria-live="polite"></p><div class="phase-legend"><span class="base-key">'+t('單獨檢索','Embedding alone')+'</span><span class="gain-key">'+t('提升','Gain')+'</span><span class="loss-key">'+t('下降','Loss')+'</span></div><div id="phase-bars" aria-live="polite"></div><button type="button" id="toggle-bars" class="chart-toggle"></button><p class="small">'+t('nDCG／MRR 的色條以分數×100呈現；差值以原始分數呈現。Top-1／Recall 差值使用百分點（pp）。','nDCG/MRR bars use score ×100; deltas use raw score units. Top-1/Recall deltas use percentage points (pp).')+'</p><h3>'+t('28 種組合完整比較｜點欄位排序','All 28 setups | click a column to sort')+'</h3><div id="phase-table" class="table-scroll" tabindex="0"></div><p class="small">'+t('綜合時間是各分項逐題平均時間的等權平均。p50／p95只在單一分項顯示，不直接平均百分位數。','Aggregate time is an equal-weight mean of task-level mean times. p50/p95 appear only for individual conditions; percentiles are not averaged.')+'</p></section>'
 b+=recommendations(lang)
 winners=[]
 for d in ORDER:
  rows=group(d);best=rows[0];top=max(r['top1'] for r in rows);meta=A['datasets'][d]
  winners.append([LABELS[d][lang],meta['queries'],f'{meta["corpus"]:,}',combo(best,lang),f'{best["ndcg10"]:.4f}',f'{top*100:.2f}%'])
 b+='<section><h2>'+t('六個分項，各自的最佳點估計','Best point estimates in each condition')+'</h2>'+tab([t('分項','Condition'),t('題數','Queries'),t('文章數','Documents'),t('nDCG最高組合','Highest-nDCG setup'),'nDCG@10',t('分項最高Top-1¹','Best task Top-1¹')],winners)+'<p class="small">'+t('¹最高Top-1可能來自另一組合，請用上方互動表按Top-1排序。ACORD命中門檻為2星以上，與原論文不同；MIRACL是有限候選語料子集。','¹Best Top-1 may belong to a different setup; sort the interactive table by Top-1. ACORD counts at least 2 stars, unlike the paper. MIRACL uses a bounded corpus subset.')+'</p></section>'
 b+='<section><h2>'+t('想看完整方法、資料或模型？','Explore methods, data and models')+'</h2><p><a href="latest-methods.html">'+t('完整說明與下載','Methods and downloads')+'</a> · <a href="models.html">'+t('每個模型的詳細頁面','Detailed model pages')+'</a> · <a href="'+pre+'data/matrix/summary.csv">168 '+t('分項結果CSV','task results: CSV')+'</a> · <a href="phase2.html">'+t('10/24前一輪結果','Previous Oct 24 results')+'</a> · <a href="baseline.html">'+t('10/22歷史22組','Historical Oct 22 matrix')+'</a></p></section>'
 payload={'lang':lang,'names':{k:name(k,lang) for k in A['names']},'labels':{k:v[lang] for k,v in LABELS.items()},'datasets':A['datasets'],'scopes':{k:group(k) for k in ['all','mlqa']+ORDER}}
 b+='<script id="phase-data" type="application/json">'+json.dumps(payload,ensure_ascii=False).replace('</','<\\/')+'</script><script src="'+pre+'assets/phase2.js" defer></script>'
 return page('index.html',t('28組中英檢索完整比較','28-setup bilingual retrieval benchmark'),b,lang)

def methods(lang):
 t=lambda z,e:tr(z,e,lang);pre='../' if lang else ''
 b='<section class="phase-hero"><p class="eyebrow">METHODS / OCTOBER 26 MATRIX</p><h1>'+t('測試怎麼做，結果能說到哪裡。','How the test works—and what it can establish.')+'</h1><p class="lead">'+t('28配置、六分項、73,164筆正式測量。這裡保留完整統計定義、驗證範圍與可下載證據。','28 setups, six conditions and 73,164 accepted measurements. Definitions, verification scope and downloadable evidence are documented here.')+'</p></section>'
 sections=[('average',t('首頁平均如何計算？','How is the homepage average calculated?'),t('先在每個分項內平均全部題目的分數，再把六個分項各給1/6權重。MLQA三項合占50%、MIRACL兩項占33.33%、ACORD占16.67%；這是方便比較的描述性選擇，不是實際使用流量的估計。28組全部完成六分項，沒有缺項補零。2,613題是資料集內唯一題目數，未跨語言去重，73,164列是重複測量。nDCG依相關性與名次計分，不是命中率；Top-1、MRR與Recall回答不同問題。','Average all query scores within each condition, then give the six condition means equal weight 1/6. MLQA contributes 50%, MIRACL 33.33% and ACORD 16.67%. This is a descriptive comparison, not an estimate of production traffic. All 28 setups complete every condition; no missing cells are filled with zero. The 2,613 count is unique within datasets, not cross-language deduplicated; 73,164 rows are repeated measurements. nDCG combines relevance and rank, not hit probability. Top-1, MRR and Recall measure different aspects.')),
 ('fairness',t('相同題目、語料與候選數，具體是什麼？','What does consistent testing mean?'),t('同一分項內，所有組合使用完全相同的題目、語料、qrels相關性標註與模型版本。每個Embedder先找前50筆，三種重排器都收到該Embedder同一份有序候選清單；獨立驗證逐題核對54,873筆重排輸入雜湊與候選集合。不同Embedder找到的文章可以不同，這正是檢索能力的一部分。重排只改變候選內的順序，不能找回50筆以外的資料。','Within each condition, every setup uses identical queries, corpus, relevance judgments and pinned model versions. Each embedder retrieves 50 candidates; its three rerankers receive the same ordered list. Independent verification checks candidate sets and input-order hashes for all 54,873 reranked rows. Different embedders can retrieve different documents; that is part of retrieval performance. Reranking cannot recover documents outside the candidate pool.')),
 ('scope',t('資料範圍與相關性定義','Data scope and relevance definitions'),t('MLQA使用固定validation方向（504／504／1,148題），包含前次每方向100題；不是全新保留集。ACORD使用57道test問題及3,931條款。MIRACL每語言200道dev問題，語料為全部dev已標註段落的聯集：中文3,786、英文7,921，並非完整百萬級語料。MLQA／MIRACL採二元相關；ACORD星等減1映射0–4，Top-1以grade>0（2星以上）命中，nDCG採2^grade−1 gain，P@5固定除以5。原ACORD論文以3–5星視為相關、採線性gain，故本站不能直接對照其分數。未標註文件以零gain計分，不等於人工判定不相關。','MLQA uses fixed validation directions (504/504/1,148 queries), including the earlier 100 per direction; this is not an untouched holdout. ACORD uses 57 test queries and 3,931 clauses. MIRACL uses 200 dev queries per language with the union of all dev-judged passages: 3,786 Chinese and 7,921 English, not the full million-scale corpus. MLQA/MIRACL use binary relevance. ACORD stars minus one map to grades 0–4: Top-1 counts grade>0 (at least 2 stars), nDCG uses gain 2^grade−1 and P@5 divides by 5. The ACORD paper treats 3–5 stars as relevant and uses linear gain, so scores are not directly comparable. Unjudged documents receive zero gain, not a human judgment of irrelevance.')),
 ('uncertainty',t('能否說第一名確定最好？','Does first place establish a reliable winner?'),t('不能。這次主榜沒有對28配置計算全域bootstrap區間或多重比較校正；0.7926與0.7917的差距只約0.0009。這些是固定資料下的點估計。前一輪Qwen4B的配對區間保留在歷史說明頁，不套用到新28組排名。ACORD只有57題且候選標註覆蓋約15–17%，不能由低分直接判定整體法律能力。MIRACL多個Embedder重排後很接近，也不能據此斷言大型語料中Embedder不重要。','No. The 28-setup leaderboard has no global bootstrap intervals or multiplicity correction; 0.7926 versus 0.7917 differs by about 0.0009. These are point estimates on fixed data. Earlier Qwen 4B paired intervals remain on the historical methods page and are not applied to the new matrix. ACORD has only 57 queries and roughly 15–17% candidate judgment coverage, so low scores do not establish general legal capability. Near-equal reranked MIRACL scores do not show that embedders are unimportant on large corpora.')),
 ('timing',t('時間與硬體限制','Timing and hardware limits'),t('Apple M3 Ultra、256 GiB統一記憶體、macOS 26.7、Q8_0、Metal全層offload；Python3.12.14、NumPy2.3.5，llama-server binary SHA256固定。server context 8192、單一parallel slot、batch／ubatch 4096；輸入含模板需通過4096-token預檢，不截斷。查詢總時間是embedding、exact search、rerank階段相加；同Embedder候選快取會重用其檢索時間。不同模型分批執行，並非隨機交錯延遲實驗；背景服務存在，但guard監控其流量。時間不含冷載入、建索引、網路、佇列或服務併發，也不是30題×3次穩定性研究。模型容量只是GGUF權重加總，不是RAM／VRAM實測。','Apple M3 Ultra, 256 GiB unified memory, macOS 26.7, Q8_0 and all-layer Metal offload; Python 3.12.14, NumPy 2.3.5 and a pinned llama-server binary. Server context is 8192 with one parallel slot and batch/ubatch 4096; inputs including templates must pass a 4096-token preflight without truncation. Query total adds embedding, exact search and reranking stages; cached candidates reuse the original retrieval timings. Models run in separate batches, not a randomized interleaved latency experiment. Background services remained present, with traffic monitored by a guard. Times exclude cold loading, indexing, network, queues and concurrency; this is not a 30-query ×3 stability study. Size is summed GGUF weights, not measured RAM/VRAM.')),
 ('published',t('與公開測量相比：一致之處與新增價值','Published findings and what this matrix adds'),t('Qwen官方報告中，4B重排器在MTEB-R、CMTEB-R、MMTEB-R均高於0.6B；本次七個Embedder各自的六分項平均也呈現相同方向。官方使用Qwen0.6B檢索的Top100，本次各Embedder固定Top50，且採Q8_0／llama.cpp／Metal，分數不可直接相減。這次新增價值是完整28組交叉比較：小Embedder＋大重排器可接近領先品質；更大Embedder未必提升重排後總平均；法律與百科的最佳組合不同。這些是本測試觀察，並非首次發現或普遍定律。','Qwen’s official evaluation scores the 4B reranker above 0.6B on MTEB-R, CMTEB-R and MMTEB-R. Each of the seven local embedders shows the same direction in its six-task mean. Qwen uses Top100 candidates from Qwen 0.6B embeddings; here each embedder supplies Top50 with Q8_0/llama.cpp/Metal, so scores cannot be subtracted directly. The added value is the complete 28-setup comparison: small embedders with large rerankers approach leading quality; larger embedders do not always improve the reranked overall mean; legal and encyclopedia tasks favor different setups. These are local observations, not first-ever discoveries or universal rules.'))]
 for id,h,text in sections:b+=f'<section id="{id}"><h2>{h}</h2><p>{text}</p></section>'
 b+='<section><h2>'+t('本次複核發現與文件勘誤','Verification findings and documentation errata')+'</h2><p>'+t('獨立重算73,164列、168組摘要與957,516個品質值，品質值完全一致；另核對54,873筆重排的候選順序雜湊。原runner產生的文字報告有一處寫standalone Top100，是過時字串，實際所有正式排名都是Top50。原碼保留以供追溯，本站已更正。MIRACL各Embedder的候選集合不同，但候選Recall@50已達99.75–100%，同一重排器很容易把相同文件排第一；這說明子集的區辨限制，並不是結果被重用或所有Embedder普遍等效。','Independent recomputation of 73,164 rows, 168 summaries and 957,516 quality values found exact quality agreement; input-order hashes were also checked for all 54,873 reranked rows. One runner-generated report sentence says standalone Top100: this is stale wording, while every accepted ranking contains Top50. Source is preserved for traceability; this site corrects the description. MIRACL candidate sets differ across embedders, but candidate Recall@50 is already 99.75–100%, allowing the same reranker to put the same document first. This limits discrimination within the subset; it does not indicate reused results or universal embedder equivalence.')+'</p></section>'
 b+='<section><h2>'+t('官方來源與評測條件','Primary sources and evaluation settings')+'</h2><p><a href="https://qwenlm.github.io/blog/qwen3-embedding/">Qwen3 official evaluation</a> · <a href="https://arxiv.org/html/2506.05176v1">Qwen3 technical report</a> · <a href="https://github.com/project-miracl/miracl">MIRACL</a> · <a href="https://aclanthology.org/2025.acl-long.1206.pdf">ACORD paper</a></p><p>'+t('2026-10-27重新核對官方頁面。Qwen報告列MIRACL為訓練資料來源之一，因此不稱未見過的新資料集；這本身也不證明dev/test資料洩漏。','Official pages rechecked on 27 Oct 2026. Qwen lists MIRACL among training sources; it is not described here as an unseen dataset. This alone does not demonstrate dev/test leakage.')+'</p></section>'
 b+='<section><h2>'+t('完整六分項數字','All six task tables')+'</h2>'
 for d in ORDER:
  b+='<details><summary>'+LABELS[d][lang]+' · 28 '+t('組合','setups')+'</summary>'+tab([t('組合','Setup'),'Top-1','nDCG@10','MRR@10','Recall@50',t('標註覆蓋@50','Judged @50'),'p50 ms','p95 ms'],[[combo(r,lang),f'{r["top1"]*100:.2f}%',f'{r["ndcg10"]:.4f}',f'{r["mrr10"]:.4f}',f'{r["recall50"]*100:.2f}%',f'{r["judged_coverage50"]*100:.2f}%',f'{r["total_ms_p50"]:.2f}',f'{r["total_ms_p95"]:.2f}'] for r in group(d)])+'</details>'
 b+='</section><section><h2>'+t('重排階段的時間取捨','Reranking-stage time tradeoffs')+'</h2>'+tab(['Reranker',t('逐題筆數','Rows'),'p50','p95',t('七Embedder平均nDCG','Mean nDCG across seven embedders')],[[name(rr,lang),x['rows'],f'{x["p50_ms"]/1000:.3f} s',f'{x["p95_ms"]/1000:.3f} s',f'{x["mean_macro_ndcg10"]:.4f}'] for rr,x in A['reranker_timing'].items()])+'<p>'+t('p50/p95直接合併同重排器的18,291次逐題時間計算；不是先算各組百分位再平均。品質欄則對各Embedder、各分項等權平均，兩者權重不同。','p50/p95 are computed directly from each reranker’s 18,291 measured query times, not by averaging group percentiles. Quality averages embedders and conditions equally; timing and quality use different weighting.')+'</p></section>'
 b+='<section id="downloads"><h2>'+t('完整結果、素材與程式','Complete results, materials and code')+'</h2><div class="downloads">'
 for batch,e in zip(['B01','B02','B03','B04','B05','B06','B07'],['qwen-4b','qwen-8b','embeddinggemma-2','qwen-0.6b','bge-m3','f2llm-v2-0.6b','granite-97m-r2']):b+=f'<a class="download" href="{pre}downloads/matrix-{batch}-results.zip"><strong>{batch} · {name(e,lang)} · 10,452 {t("筆","rows")}</strong><span>ZIP ↓</span></a>'
 for file,label in [('matrix-shared.zip',t('六分項共同選題與qrels','Shared query selection and qrels')),('matrix-code.zip',t('完整矩陣程式與離線驗證器','Complete matrix code and offline verifier')),('phase2-materials.zip',t('相同凍結測試素材','The same frozen test materials'))]:b+=f'<a class="download" href="{pre}downloads/{file}"><strong>{label}</strong><span>ZIP ↓</span></a>'
 b+='</div><p>'+t('每批結果包含完整逐題排名與分數、時間、摘要及公開metadata。逐題結果／摘要保留原始位元；manifest移除本機私人路徑，原始SHA仍保留於provenance。B02由A/B兩個正式子批合併。素材包的MLQA／ACORD全文與前輪相同；MIRACL提供問題、qrels、corpus IDs及固定來源重建工具，不重新散布文章全文。','Batch archives include every query ranking, score, timing, summary and public metadata. Row/summary bytes are unchanged; manifests omit private local paths, with original hashes retained in provenance. B02 combines two accepted subbatches. MLQA/ACORD full inputs are unchanged from the previous release; MIRACL includes queries, qrels, corpus IDs and a pinned-source reconstruction tool, without repackaged passage text.')+'</p><p><a href="'+pre+'research/matrix/README.md">'+t('重現指引','Reproduction guide')+'</a> · <a href="'+pre+'data/matrix/summary.csv">CSV</a> · <a href="'+pre+'data/matrix/analysis.json">JSON</a> · <a href="'+pre+'data/matrix/independent-audit.json">'+t('獨立驗證報告','Independent verification')+'</a> · <a href="'+pre+'data/matrix/provenance.json">Provenance</a></p><p><code>python scripts/verify_matrix.py</code> '+t('可離線重算正式矩陣，不啟動模型。公開包不包含內部GPU／流量日誌與失敗attempt；其凍結稽核由NAS保留。','recomputes the accepted matrix offline without loading models. Internal GPU/traffic logs and failed attempts remain in the NAS archive, outside the public package.')+'</p></section>'
 b+='<section id="license"><h2>'+t('授權、改動與來源','Licenses, adaptations and sources')+'</h2><p>'+t('MLQA採CC BY-SA 3.0；ACORD採CC BY 4.0；MIRACL topics/qrels採Apache 2.0，Wikipedia段落另保留上游來源與適用條款。改動包括檢索格式、固定選題與群聚metadata，ACORD星等轉0–4。MIT程式授權不取代資料或各模型授權，模型權重不隨附。','MLQA uses CC BY-SA 3.0; ACORD CC BY 4.0; MIRACL topics/qrels Apache 2.0, with Wikipedia passages retaining upstream attribution and applicable terms. Adaptations include retrieval formatting, frozen selection and cluster metadata, and ACORD stars mapped to grades 0–4. The code’s MIT license does not replace dataset or model licenses; model weights are not included.')+'</p><p><a href="https://github.com/facebookresearch/MLQA">MLQA / Facebook Research</a> · <a href="https://huggingface.co/datasets/theatticusproject/acord">ACORD / The Atticus Project</a> · <a href="https://huggingface.co/datasets/miracl/miracl">MIRACL topics/qrels</a> · <a href="https://huggingface.co/datasets/miracl/miracl-corpus">MIRACL corpus</a></p></section>'
 return page('latest-methods.html',t('完整28組：方法、限制與資料','Complete 28-setup matrix: methods and data'),b,lang)

def build():
 # The earlier generator retains the v3 baseline and Oct 24 release.
 old.build()
 for lang in [0,1]:
  folder=ROOT/('en' if lang else '')
  for src,dst in [('index.html','phase2.html'),('latest-methods.html','phase2-methods.html')]:
   s=(folder/src).read_text('utf-8')
   s=s.replace('index.html','phase2.html').replace('latest-methods.html','phase2-methods.html')
   s=s.replace('<main id="main">','<main id="main"><p class="note">'+tr('歷史版本｜10/24；','Historical Oct 24 release; ',lang)+'<a href="index.html">'+tr('查看最新28組','View the latest 28 setups',lang)+'</a></p>')
   (folder/dst).write_text(s,encoding='utf-8')
 old.A=A
 for lang in [0,1]:
  folder=ROOT/('en' if lang else '');t=lambda z,e:tr(z,e,lang)
  for p in [folder/'models.html',folder/'methods.html',folder/'resources.html',*sorted((folder/'models').glob('*.html'))]:
   s=p.read_text('utf-8');prefix='../' if p.parent.name=='models' else ''
   notice='<aside class="note"><strong>'+t('2026-10-26 完整28組矩陣','Complete 28-setup matrix · 26 Oct 2026')+'</strong> · <a href="'+prefix+'index.html">'+t('最新綜合比較','Latest comparison')+'</a> · <a href="'+prefix+'latest-methods.html">'+t('方法與完整下載','Methods and all downloads')+'</a></aside>'
   if p.parent.name=='models':
    key=p.stem;rows=[r for r in A['rows'] if key in [r['embedding'],r['reranker']]]
    notice+='<section><h2>'+t('最新完整矩陣實測','Latest complete-matrix results')+'</h2><p>'+t('下表涵蓋此模型的所有已測配對與六分項；依分項、nDCG排序。容量為權重檔案大小，時間只含已暖機的查詢階段。','All measured pairings and six conditions for this model, ordered by condition and nDCG. Size is weight-file size; timing covers warmed query stages only.')+'</p>'
    notice+=tab([t('分項','Condition'),t('組合','Setup'),'Top-1','nDCG@10','Recall@50','p50 ms','p95 ms'],[[LABELS[r['dataset']][lang],combo(r,lang),f'{r["top1"]*100:.2f}%',f'{r["ndcg10"]:.4f}',f'{r["recall50"]*100:.2f}%',f'{r["total_ms_p50"]:.2f}',f'{r["total_ms_p95"]:.2f}'] for r in sorted(rows,key=lambda r:(ORDER.index(r['dataset']),-r['ndcg10']))])+'</section>'
    marker=t('<h2>模型介紹與10/22歷史結果</h2>','<h2>Model background and Oct 22 historical results</h2>')
    start=s.index('<main id="main">')+len('<main id="main">');end=s.index(marker,start)
    s=s[:start]+notice+s[end:]
   else:
    s=re.sub(r'<aside class="note">.*?</aside>',notice,s,count=1,flags=re.S)
   p.write_text(s,encoding='utf-8')
  (folder/'index.html').write_text(home(lang),encoding='utf-8')
  (folder/'latest-methods.html').write_text(methods(lang),encoding='utf-8')
 for p in ROOT.rglob('*.html'):
  s=p.read_text('utf-8')
  for asset in ['assets/style.css','assets/phase2.css','assets/phase2.js']:
   s=s.replace(asset+'"',asset+'?v=20261027"')
  p.write_text(s,encoding='utf-8')
 urls=sorted(str(p.relative_to(ROOT)).replace('\\','/') for p in ROOT.rglob('*.html'))
 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+old.SITE+p+'</loc><lastmod>2026-10-27</lastmod></url>' for p in urls)+'</urlset>',encoding='utf-8')
 print('Built bilingual full matrix;',len(urls),'pages')
